draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw peach
  ctx.fillStyle = '#ffc5c5';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw fuzzy stone
  ctx.fillStyle = '#666666';
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 30, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.lineWidth = 2;
  for (let i = 0; i < 10; i++) {
    ctx.moveTo(W/2 + 100 + 30 + Math.cos(i) * 10, H/2 + 30 + Math.sin(i) * 10);
    ctx.lineTo(W/2 + 100 + 30 + Math.cos(i + Math.sin(t)) * 10, H/2 + 30 + Math.sin(i + Math.sin(t)) * 10);
  }
  ctx.stroke();

  // draw sweet
  ctx.font = '24px Arial';
  ctx.fillStyle = 'black';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillText('Sweet', W/2 + 150, H/2 - 50 + 20 * Math.sin(t));

  ctx.restore();
}
